// learning and its Chinese; a word you haven't caught yet, in your tasks, is just its Chinese). tools/ui-strings.js finds
// every piece of text there is (node tools/ui-strings.js --missing lists those still without their Chinese), and
// tests/chinese-ui.test.js checks each has one. Written by Claude, to be checked by a native speaker (decided 9 November
// 2026: a paid professional checks it).
